const RunStateSpec* GetRunStateSpecs(){return kSpecs;} std::size_t GetRunStateSpecCount(){return sizeof(kSpecs)/sizeof(kSpecs[0]);}
const RunStateSpec* FindRunStateSpec(std::uint32_t a){auto b=kSpecs,e=kSpecs+GetRunStateSpecCount();auto i=std::find_if(b,e,[a](const RunStateSpec&s){return s.retail_address==a;});return i==e?nullptr:i;}
RunStateWord InvokeRunState(RunStateRuntime&r,std::uint32_t a,const RunStateWord*x,std::size_t n){auto*s=FindRunStateSpec(a);return (!s||!r.invoke)?0:r.invoke(r.user,*s,x,n);}
